import{_ as n,o as t,c as a,a2 as s}from"./chunks/framework.5akMI7mQ.js";const m=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/architecture.md","filePath":"getting-started/architecture.md","lastUpdated":1792429063000}'),i={name:"getting-started/architecture.md"};function o(r,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>This document details the internal design and architectural components of <strong>Wednes Serverless Engine</strong>.</p><hr><h2 id="high-level-request-pipeline" tabindex="-1">High-Level Request Pipeline <a class="header-anchor" href="#high-level-request-pipeline" aria-label="Permalink to &quot;High-Level Request Pipeline&quot;">​</a></h2><p>Every incoming HTTP or QUIC request flows through an admission and sandboxed execution pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ HTTP/1.1 / HTTP/2 Client ]      [ HTTP/3 QUIC Client ]</span></span>
<span class="line"><span>             │                               │</span></span>
<span class="line"><span>             ▼ (TCP)                         ▼ (UDP)</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>     |                 axum Router                   |</span></span>
<span class="line"><span>     |         (Route: /fn/:id and /fn/:id/*path)    |</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>     |                   Scheduler                   |</span></span>
<span class="line"><span>     |  - Global Concurrency Semaphore               |</span></span>
<span class="line"><span>     |  - Memory Budget Admission                    |</span></span>
<span class="line"><span>     |  - Per-Function Concurrency Semaphore         |</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>                             │ (Permit Acquired)</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>     |             WasmtimeBackend Engine            |</span></span>
<span class="line"><span>     |  - Compiled Component Cache (in-memory)       |</span></span>
<span class="line"><span>     |  - Fresh wasmtime::Store creation             |</span></span>
<span class="line"><span>     |  - StoreLimits (memory_mb bound)              |</span></span>
<span class="line"><span>     |  - Epoch Interruption (timeout_ms bound)      |</span></span>
<span class="line"><span>     |  - WASI P1/P2 Context Sandbox                 |</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>                             │</span></span>
<span class="line"><span>                             ▼</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span>
<span class="line"><span>     |            Guest Component Execution          |</span></span>
<span class="line"><span>     |           ABI: wednes:function@0.1.0          |</span></span>
<span class="line"><span>     |             handle(request) -&gt; response       |</span></span>
<span class="line"><span>     +───────────────────────────────────────────────+</span></span></code></pre></div><hr><h2 id="crate-modularization" tabindex="-1">Crate Modularization <a class="header-anchor" href="#crate-modularization" aria-label="Permalink to &quot;Crate Modularization&quot;">​</a></h2><p>Wednes Serverless Engine is architected as an idiomatic Rust workspace composed of focused crates:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Crate</th><th style="text-align:left;">Responsibilities</th></tr></thead><tbody><tr><td style="text-align:left;"><strong><code>wednes-cli</code></strong></td><td style="text-align:left;">The <code>wednesd</code> daemon entrypoint, argument parsing via <code>clap</code>, subcommands (<code>init</code>, <code>dev</code>, <code>deploy</code>, <code>run</code>), and legacy single-component loader.</td></tr><tr><td style="text-align:left;"><strong><code>wednes-gateway</code></strong></td><td style="text-align:left;">Network ingress, <code>axum</code> routing for <code>/fn/:id</code> and <code>/fn/:id/*path</code>, HTTP/3 QUIC server setup via <code>quinn</code> and <code>rustls</code>, and scheduling semaphores.</td></tr><tr><td style="text-align:left;"><strong><code>wednes-core</code></strong></td><td style="text-align:left;">Domain types (<code>Request</code>, <code>Response</code>, <code>Header</code>), strict manifest validation (<code>wednes.yaml</code> / <code>manifest.toml</code>), and atomic file registry (<code>registry.json</code>).</td></tr><tr><td style="text-align:left;"><strong><code>wednes-runtime</code></strong></td><td style="text-align:left;">Abstract <code>RuntimeBackend</code> trait defining execution interfaces, lifecycle hooks, and common errors.</td></tr><tr><td style="text-align:left;"><strong><code>wednes-runtime-wasmtime</code></strong></td><td style="text-align:left;">Concrete Wasmtime implementation: JIT compilation, pre-instance caching (<code>instantiate_pre</code>), typed export checking, epoch background timer, and WASI builder.</td></tr><tr><td style="text-align:left;"><strong><code>wednes-capabilities</code></strong></td><td style="text-align:left;">Security boundaries and capability verification (filesystem access, network policies, outbound HTTP admission).</td></tr><tr><td style="text-align:left;"><strong><code>wednes-telemetry</code></strong></td><td style="text-align:left;">Structured JSON logging (<code>--log-json</code>), tracing spans, and runtime latency tracking.</td></tr></tbody></table><hr><h2 id="sandboxed-execution-lifecycle" tabindex="-1">Sandboxed Execution Lifecycle <a class="header-anchor" href="#sandboxed-execution-lifecycle" aria-label="Permalink to &quot;Sandboxed Execution Lifecycle&quot;">​</a></h2><h3 id="_1-ingress-admission-control" tabindex="-1">1. Ingress &amp; Admission Control <a class="header-anchor" href="#_1-ingress-admission-control" aria-label="Permalink to &quot;1. Ingress &amp; Admission Control&quot;">​</a></h3><p>When an HTTP request arrives at <code>axum</code>:</p><ol><li>The function identifier <code>:id</code> is extracted from the URL.</li><li>The <code>Scheduler</code> checks whether the function is registered. If missing, it returns <code>404 Not Found</code>.</li><li>The scheduler requests two semaphore permits: <ul><li><strong>Global Concurrency Permit:</strong> Bounded by <code>--global-concurrency</code> (default: 100).</li><li><strong>Per-Function Concurrency Permit:</strong> Configured per-function in manifest (default: 16).</li></ul></li><li>If either semaphore is saturated, the gateway immediately rejects the request with <code>429 Too Many Requests</code>. This prevents cascading memory exhaustion or unbounded event queues.</li></ol><h3 id="_2-precompiled-component-cache" tabindex="-1">2. Precompiled Component Cache <a class="header-anchor" href="#_2-precompiled-component-cache" aria-label="Permalink to &quot;2. Precompiled Component Cache&quot;">​</a></h3><p>Compilation of WebAssembly bytecode to native machine code via Cranelift is computationally intensive. To achieve sub-millisecond execution:</p><ul><li>At deploy/load time, the component is parsed, validated against the WIT contract <code>wednes:function@0.1.0</code>, and pre-instantiated.</li><li>The compiled component bytecode resides in memory as an immutable template across the lifetime of the daemon process.</li></ul><h3 id="_3-per-invocation-store-isolation" tabindex="-1">3. Per-Invocation Store Isolation <a class="header-anchor" href="#_3-per-invocation-store-isolation" aria-label="Permalink to &quot;3. Per-Invocation Store Isolation&quot;">​</a></h3><p>For each request:</p><ul><li>A new, clean <code>wasmtime::Store</code> is created.</li><li>A fresh linear memory instance is mapped.</li><li>State is strictly isolated: no shared global memory, static mutation, or dirty state can leak between requests or across different callers.</li><li>After the request finishes, the <code>Store</code> is dropped and linear memory is immediately reclaimed by the OS.</li></ul><h3 id="_4-epoch-trapping-memory-limits" tabindex="-1">4. Epoch Trapping &amp; Memory Limits <a class="header-anchor" href="#_4-epoch-trapping-memory-limits" aria-label="Permalink to &quot;4. Epoch Trapping &amp; Memory Limits&quot;">​</a></h3><p>To prevent runaway scripts:</p><ul><li><strong>Memory Enforcement:</strong> <code>StoreLimits</code> bounds linear memory growth according to the function&#39;s <code>memory_mb</code> limit (1 MB to 2048 MB).</li><li><strong>CPU Timeouts:</strong> A background epoch incrementer ticks continuously. If a function exceeds its <code>timeout_ms</code> budget (e.g., in an infinite loop), Wasmtime triggers an epoch trap, aborting execution and returning an internal execution error without crashing <code>wednesd</code>.</li></ul><hr><h2 id="atomic-registry-architecture" tabindex="-1">Atomic Registry Architecture <a class="header-anchor" href="#atomic-registry-architecture" aria-label="Permalink to &quot;Atomic Registry Architecture&quot;">​</a></h2><p>Wednes uses an atomic, transactional local registry model (<code>registry.json</code>):</p><ol><li><strong>Deployment Phase:</strong><ul><li>The user runs <code>wednesd deploy --manifest manifest.toml --registry registry.json</code>.</li><li>The manifest is parsed and checked against strict validation constraints.</li><li>The <code>.wasm</code> binary is checked for exports conforming to <code>wednes:function@0.1.0</code>.</li></ul></li><li><strong>Atomic Swap:</strong><ul><li>The new registry is written to a temporary sibling file (e.g., <code>registry.json.tmp.12345</code>).</li><li>The temporary file is atomically renamed (<code>std::fs::rename</code>) over <code>registry.json</code>.</li><li>On POSIX filesystems, this rename is guaranteed to be atomic. Readers never observe corrupted or half-written registry states.</li></ul></li><li><strong>Rollback Guarantee:</strong><ul><li>If validation or precompilation fails at any step, the temporary file is purged and the existing registry remains untouched.</li></ul></li></ol><hr><h2 id="security-boundaries-operator-model" tabindex="-1">Security Boundaries &amp; Operator Model <a class="header-anchor" href="#security-boundaries-operator-model" aria-label="Permalink to &quot;Security Boundaries &amp; Operator Model&quot;">​</a></h2><ul><li><strong>Untrusted Guests:</strong> Guest WASM code is strictly untrusted.</li><li><strong>Trusted Operator:</strong> Host OS, daemon binary, file registry, and build pipeline belong to the trusted boundary.</li><li><strong>Closed-by-Default WASI:</strong> Guests have no access to host directories, no environment variables, and cannot spawn host child processes.</li><li><strong>Reverse Proxy Recommended:</strong> When exposing <code>wednesd</code> to the public internet, place it behind an authenticated reverse proxy (such as Traefik, Nginx, or Cloudflare Tunnel) to handle rate limiting and public TLS termination.</li></ul>`,31)])])}const h=n(i,[["render",o]]);export{m as __pageData,h as default};
